/*
 * [算法說明]
 * 本題要求找出字串 s 的最大重複次數 n，使得 s = a^n。
 * 這是尋找字串「最小週期」的經典問題，可以使用 KMP 算法中的「前綴函數」(Failure Function / Next Array) 來解決。
 * 
 * 1. 對字串 s 計算 KMP 的前綴函數 pi[]，其中 pi[i] 表示 s[0...i] 的最長相等真前後綴的長度。
 * 2. 令 L 為字串 s 的總長度。pi[L-1] 則是整個字串的最長相等真前後綴長度。
 * 3. 最小可能的週期長度 P 為 L - pi[L-1]。
 * 4. 如果 L 能被 P 整除 (L % P == 0)，則字串由長度為 P 的子串重複 L/P 次構成。最大次數 n = L/P。
 * 5. 如果不能整除，則最大重複次數 n = 1 (即 s = s^1)。
 */

#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
    string s;
    while (cin >> s && s != ".") {
        int n = s.length();
        vector<int> pi(n);
        for (int i = 1, j = 0; i < n; i++) {
            while (j > 0 && s[i] != s[j])
                j = pi[j - 1];
            if (s[i] == s[j])
                j++;
            pi[i] = j;
        }

        int last_pi = pi[n - 1];
        int period = n - last_pi;
        if (n % period == 0) {
            cout << n / period << endl;
        } else {
            cout << 1 << endl;
        }
    }
    return 0;
}
